import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Desnpdez.js";const u=JSON.parse('{"title":"Data directory","description":"","frontmatter":{},"headers":[],"relativePath":"reference/data-directory.md","filePath":"reference/data-directory.md"}'),n={name:"reference/data-directory.md"};function i(s,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="data-directory" tabindex="-1">Data directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data directory&quot;">​</a></h1><p>MindBehindAI keeps its files in one folder on your computer. Nothing lives “inside a container” for the assistant bridge—everything is normal files you can back up.</p><h2 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h2><p><strong>macOS:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/MindBehind/mcp-orchestrator/</span></span></code></pre></div><p><strong>Windows:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%APPDATA%\\MindBehind\\mcp-orchestrator\\</span></span></code></pre></div><h2 id="open-in-finder-or-explorer" tabindex="-1">Open in Finder or Explorer <a class="header-anchor" href="#open-in-finder-or-explorer" aria-label="Permalink to &quot;Open in Finder or Explorer&quot;">​</a></h2><p>Use <strong>Settings → Data Directory → Open</strong>, or the <strong>File → Open Data Folder</strong> menu entry.</p><h2 id="what-the-files-mean" tabindex="-1">What the files mean <a class="header-anchor" href="#what-the-files-mean" aria-label="Permalink to &quot;What the files mean&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File / folder</th><th>Purpose</th></tr></thead><tbody><tr><td><code>servers.json</code></td><td>All <strong>connections</strong> (names, commands, enabled flags).</td></tr><tr><td><code>config.json</code></td><td>Generated bridge configuration (rebuilt when you start or apply changes).</td></tr><tr><td><code>orchestrator-settings.json</code></td><td>Port, advanced flag, and related app settings.</td></tr><tr><td><code>license/</code></td><td>Encrypted license material.</td></tr><tr><td><code>oauth-tokens/</code></td><td>Saved OAuth sessions for providers such as Telekom or Microsoft.</td></tr><tr><td><code>.mindbehind-docker-cli/</code></td><td>Cached helper for presets that still call Docker on the host.</td></tr></tbody></table><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>The app keeps automatic backups of <code>servers.json</code>. For your own backup, copy at least <code>servers.json</code> and <code>orchestrator-settings.json</code> before big experiments.</p><h2 id="moving-to-a-new-computer" tabindex="-1">Moving to a new computer <a class="header-anchor" href="#moving-to-a-new-computer" aria-label="Permalink to &quot;Moving to a new computer&quot;">​</a></h2><ol><li>Copy the whole <code>mcp-orchestrator</code> folder into the same path on the new machine (see <strong>Location</strong> above).</li><li>Install MindBehindAI there and launch it.</li></ol><p>You may need to <strong>re-activate your license</strong> if the device identity changes—contact MindBehind IT if activation fails.</p>',16)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
